create table if not exists public.registration_requests (
  id uuid primary key default gen_random_uuid(),
  school_id uuid not null references public.schools(id) on delete cascade,
  candidate_first_name text not null check (char_length(trim(candidate_first_name)) between 1 and 120),
  candidate_last_name text not null check (char_length(trim(candidate_last_name)) between 1 and 120),
  birth_date date not null,
  birth_place text,
  gender text check (gender in ('female','male','other','undisclosed')),
  guardian_name text not null check (char_length(trim(guardian_name)) between 1 and 180),
  guardian_phone text not null check (char_length(trim(guardian_phone)) between 4 and 40),
  requested_class_id uuid references public.classes(id) on delete set null,
  status text not null default 'pending' check (status in ('pending','accepted','rejected')),
  internal_note text,
  processed_at timestamptz,
  processed_by uuid references auth.users(id) on delete set null,
  created_at timestamptz not null default now()
);
create index if not exists registration_requests_school_status_idx on public.registration_requests (school_id, status, created_at desc);
alter table public.registration_requests enable row level security;
create policy registration_requests_approved_member_access on public.registration_requests for all to authenticated using (schooly_private.is_approved_school_member(school_id)) with check (schooly_private.is_approved_school_member(school_id));
create policy registration_requests_platform_admin on public.registration_requests for all to authenticated using (schooly_private.is_platform_admin()) with check (schooly_private.is_platform_admin());

create or replace function public.public_registration_school(p_slug text) returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  target_school public.schools;
  class_list jsonb;
begin
  select * into target_school from public.schools where slug = lower(trim(p_slug)) and approval_status = 'approved';
  if target_school.id is null then return null; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id', class_item.id, 'name', class_item.name, 'level', class_item.level_name) order by class_item.level_name, class_item.name), '[]'::jsonb) into class_list from public.classes class_item join public.academic_years year_item on year_item.id = class_item.academic_year_id where class_item.school_id = target_school.id and year_item.is_current = true;
  return jsonb_build_object('school', jsonb_build_object('name', target_school.name, 'slug', target_school.slug, 'city', target_school.city, 'country', target_school.country, 'phone', target_school.phone, 'logo_url', target_school.logo_url), 'classes', class_list);
end;
$$;

create or replace function public.submit_public_registration(p_slug text, p_candidate_first_name text, p_candidate_last_name text, p_birth_date date, p_birth_place text, p_gender text, p_guardian_name text, p_guardian_phone text, p_requested_class_id uuid default null) returns uuid language plpgsql security definer set search_path = public as $$
declare
  target_school public.schools;
  registration_id uuid;
begin
  select * into target_school from public.schools where slug = lower(trim(p_slug)) and approval_status = 'approved';
  if target_school.id is null then raise exception 'Établissement introuvable ou non disponible'; end if;
  if p_requested_class_id is not null and not exists (select 1 from public.classes where id = p_requested_class_id and school_id = target_school.id) then raise exception 'Classe demandée invalide'; end if;
  insert into public.registration_requests (school_id, candidate_first_name, candidate_last_name, birth_date, birth_place, gender, guardian_name, guardian_phone, requested_class_id) values (target_school.id, trim(p_candidate_first_name), trim(p_candidate_last_name), p_birth_date, nullif(trim(p_birth_place), ''), nullif(trim(p_gender), ''), trim(p_guardian_name), trim(p_guardian_phone), p_requested_class_id) returning id into registration_id;
  return registration_id;
end;
$$;
revoke all on function public.public_registration_school(text) from public;
revoke all on function public.submit_public_registration(text, text, text, date, text, text, text, text, uuid) from public;
grant execute on function public.public_registration_school(text) to anon, authenticated;
grant execute on function public.submit_public_registration(text, text, text, date, text, text, text, text, uuid) to anon, authenticated;
